// Build "Make one" (/make/) and the gallery's snippets into site-dist/: one template per scene
// variant (site/make/make.mjs snippetEntry, bundled with only the bricks it imports), the page's
// script, and a drop-in snippet for every gallery entry made from a prompt. The matcher and its
// recipe table (site/make/make.mjs, site/make/table.json) are generated by the engine's
// `fe anim export`: the same prompt makes the same file here, in the browser and in the factory.
import { build } from "esbuild";
import { gzipSync } from "node:zlib";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { makeSnippet, matchPrompt, snippetEntry, TEMPLATE_BUILD, variantOf, variants } from "../site/make/make.mjs";

export const TABLE = JSON.parse(readFileSync("site/make/table.json", "utf8"));
const gz = (text) => gzipSync(Buffer.from(text)).length;

/** A variant's template, bundled from site/gallery/scenes and src/ (the factory builds the same bytes). */
export async function template(variant) {
  const r = await build({ ...TEMPLATE_BUILD, stdin: { contents: snippetEntry(variant, { slot: "../../src/slot", fx: "../../src/fx", scenes: "../gallery/scenes" }), resolveDir: "site/make", loader: "js" } });
  return r.outputFiles[0].text;
}

/** The snippet for a prompt, made in Node the way the page makes it in the browser. */
export async function snippetFor(prompt, { version, templates, id } = {}) {
  const spec = matchPrompt(TABLE, prompt);
  if (id) spec.id = id;
  const v = variantOf(TABLE, spec);
  const code = templates?.[v] ?? (await template(v));
  return { spec, variant: v, ...(await makeSnippet(TABLE, spec, code, { version, gzipSize: gz })) };
}

/**
 * An entry Make one can make again: made by fe anim with a recipe in this table, and its prompt still
 * picks that recipe (entries made from recipes or scenes this table doesn't have yet get no snippet).
 */
export const snippetable = (e) => e.made === "fe anim" && e.recipe in TABLE.recipes && matchPrompt(TABLE, e.prompt).recipe === e.recipe;

/**
 * site-dist/make/templates/<variant>.json ({ variant, version, code }), site-dist/make/make.js (the
 * page's script, measured: its badge) and site-dist/gallery/<id>.snippet.txt for every entry made by
 * fe anim (its "Get the snippet" key). Returns { script, templates, snippets } with sizes.
 */
export async function buildMake(out, { version, entries }) {
  mkdirSync(join(out, "make/templates"), { recursive: true });
  const templates = {};
  for (const v of variants(TABLE)) {
    templates[v] = await template(v);
    writeFileSync(join(out, "make/templates", `${v}.json`), JSON.stringify({ variant: v, version, code: templates[v] }));
  }
  const r = await build({ ...TEMPLATE_BUILD, entryPoints: ["site/make/page.mjs"], define: { FIZLET_VERSION: JSON.stringify(version) } });
  writeFileSync(join(out, "make/make.js"), r.outputFiles[0].contents);
  const snippets = {};
  for (const e of entries.filter(snippetable)) {
    const s = await snippetFor(e.prompt, { version, templates, id: e.id });
    writeFileSync(join(out, "gallery", `${e.id}.snippet.txt`), s.text);
    snippets[e.id] = { file: `${e.id}.snippet.txt`, size: s.size };
  }
  return { script: gzipSync(r.outputFiles[0].contents).length, templates, snippets };
}
